using System.ComponentModel;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to ToolStripSystemRenderer instead of
    // ToolStripProfessionalRenderer. Explicitly set the renderer to preserve .NET 8 appearance.
    public StatusStrip CreateStatusStrip()
    {
        var statusStrip = new StatusStrip();
        statusStrip.RenderMode = ToolStripRenderMode.Professional;
        return statusStrip;
    }

    // .NET 9 breaking change: DropDownControl no longer accepts null.
    // Guard against null to avoid ArgumentNullException.
    public void ShowEditor(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }

    // .NET 9 breaking change: P/Invoke with SetLastError should use
    // Marshal.GetLastPInvokeError() instead of Marshal.GetLastWin32Error()
    // for correct behavior with the runtime's error tracking.
    [DllImport("user32.dll", SetLastError = true)]
    private static extern IntPtr FindWindow(string? lpClassName, string? lpWindowName);

    public IntPtr FindNativeWindow(string className)
    {
        IntPtr hwnd = FindWindow(className, null);
        if (hwnd == IntPtr.Zero)
        {
            int error = Marshal.GetLastPInvokeError();
            throw new InvalidOperationException($"FindWindow failed with error code {error}");
        }
        return hwnd;
    }
}

